//404af0 emitter dispatch.405c60 and the separate150x48 chunk constructors are boundaries.
import ghidra.app.emulator.EmulatorHelper;
import java.io.PrintWriter;
public class ZNativeAmbientEmitterOracle extends ZNativeWorldEffectOracle{
 int eh,events;
 void event(int...vs){events++;for(int v:vs)eh=(eh^v)*16777619;}
 void execute(EmulatorHelper e,int x,int y,int heading)throws Exception{eh=0x811c9dc5;events=0;calls=0;e.writeRegister("ESP",S);put(e,S,4,RET);put(e,S+4,4,y);put(e,S+8,4,heading);e.writeRegister("ECX",O);e.writeRegister("EDX",x);e.setBreakpoint(toAddr(RET));if(!e.run(toAddr(0x404af0),null,monitor))throw new Exception(e.getLastError());while(e.readRegister("EIP").longValue()!=RET){long pc=e.readRegister("EIP").longValue(),sp=e.readRegister("ESP").longValue();if(pc==0x460910)e.writeRegister("EAX",(seed*7919^(calls++)*2027^0x7731a5c9)&0xffffffffL);else if(pc==0x405c60){int[]v=new int[12];v[0]=0;v[1]=(short)e.readRegister("ECX").intValue();v[2]=(short)e.readRegister("EDX").intValue();for(int i=0;i<9;i++)v[i+3]=(int)read(e,sp+4+i*4,4);event(v);e.writeRegister("EAX",O+0x400);}else if(pc==0x41d500||pc==0x41d5d0){event(pc==0x41d500?1:2,(short)e.readRegister("EDX").intValue(),(short)read(e,sp+4,4),(int)read(e,e.readRegister("ECX").longValue()+35,1));}else throw new Exception("Unexpected "+Long.toHexString(pc));long r=read(e,sp,4);e.writeRegister("ESP",sp+4);if(!e.run(toAddr(r),null,monitor))throw new Exception(e.getLastError());}}
 public void run()throws Exception{try(PrintWriter out=new PrintWriter(getScriptArgs()[0])){EmulatorHelper e=new EmulatorHelper(currentProgram);try{for(long a:new long[]{0x405c60,0x41d500,0x41d5d0,0x460910})e.setBreakpoint(toAddr(a));int[][]points={{346,420},{-17,-33},{0,0},{32767,-32768}};for(int kind=0;kind<26;kind++)for(seed=0;seed<256;seed++){e.writeMemory(toAddr(O),new byte[62]);put(e,O+18,2,kind==25?-1:kind);put(e,O+35,1,seed*13);int[]p=points[seed/64];execute(e,p[0],p[1],seed);out.println("{\"scenario\":"+(kind*256+seed)+",\"calls\":"+calls+",\"events\":"+events+",\"eventHash\":"+(eh&0xffffffffL)+"}");}}finally{e.dispose();}}}
}
